import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Analytics = ({ token }) => {
  const [stats, setStats] = useState({
    totalEntries: 0,
    totalAmount: 0,
    anomalies: 0,
    categories: {},
    timelineData: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAnalytics();
  }, []);

  const fetchAnalytics = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/ledger-entries?page=1&per_page=1000', {
        headers: { Authorization: `Bearer ${token}` }
      });

      const entries = response.data.entries || [];
      const totalEntries = entries.length;
      const totalAmount = entries.reduce((sum, entry) => sum + entry.amount, 0);
      const anomalies = entries.filter(entry => entry.is_anomaly).length;

      // Category breakdown
      const categories = {};
      entries.forEach(entry => {
        categories[entry.category] = (categories[entry.category] || 0) + entry.amount;
      });

      // Timeline data
      const timelineMap = {};
      entries.forEach(entry => {
        const date = entry.date;
        if (!timelineMap[date]) {
          timelineMap[date] = { date, normal: 0, anomaly: 0 };
        }
        if (entry.is_anomaly) {
          timelineMap[date].anomaly += 1;
        } else {
          timelineMap[date].normal += 1;
        }
      });
      const timelineData = Object.values(timelineMap).sort((a, b) => new Date(a.date) - new Date(b.date)).slice(-10);

      setStats({
        totalEntries,
        totalAmount,
        anomalies,
        categories,
        timelineData
      });
      setLoading(false);
    } catch (error) {
      console.error('Error fetching analytics:', error);
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR'
    }).format(amount);
  };

  if (loading) {
    return (
      <div className="page-content">
        <div className="loading">Loading analytics...</div>
      </div>
    );
  }

  const normalCount = stats.totalEntries - stats.anomalies;
  const anomalyPercentage = stats.totalEntries > 0 ? (stats.anomalies / stats.totalEntries) * 100 : 0;
  const normalPercentage = 100 - anomalyPercentage;

  return (
    <div className="page-content">
      {/* Stats Cards */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">📊</div>
          <div className="stat-content">
            <h3>Total Entries</h3>
            <div className="stat-number">{stats.totalEntries}</div>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">💰</div>
          <div className="stat-content">
            <h3>Total Amount</h3>
            <div className="stat-number">{formatCurrency(stats.totalAmount)}</div>
          </div>
        </div>

        <div className="stat-card anomaly">
          <div className="stat-icon">⚠️</div>
          <div className="stat-content">
            <h3>Anomalies</h3>
            <div className="stat-number">{stats.anomalies}</div>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📈</div>
          <div className="stat-content">
            <h3>Anomaly Rate</h3>
            <div className="stat-number">{anomalyPercentage.toFixed(1)}%</div>
          </div>
        </div>
      </div>

      {/* ML Process Flow Diagram */}
      <div className="card">
        <h2>🤖 Machine Learning Detection Process</h2>
        <div className="ml-process-flow">
          <div className="process-step">
            <div className="step-icon">📥</div>
            <div className="step-content">
              <h3>1. Data Input</h3>
              <p>Transaction submitted</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">🔧</div>
            <div className="step-content">
              <h3>2. Feature Extraction</h3>
              <p>6 features extracted</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">🧠</div>
            <div className="step-content">
              <h3>3. Isolation Forest</h3>
              <p>ML model analyzes</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">✅</div>
            <div className="step-content">
              <h3>4. Classification</h3>
              <p>Normal/Anomaly</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">📧</div>
            <div className="step-content">
              <h3>5. Alert</h3>
              <p>Email notification</p>
            </div>
          </div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="charts-grid">
        {/* Anomaly Distribution */}
        <div className="card chart-card">
          <h2>📊 Anomaly Distribution</h2>
          {stats.totalEntries > 0 ? (
            <div className="custom-pie-chart">
              <div className="pie-chart-container">
                <svg viewBox="0 0 200 200" className="pie-svg">
                  <circle cx="100" cy="100" r="80" fill="#10b981" 
                    strokeDasharray={`${normalPercentage * 5.03} 503`} 
                    transform="rotate(-90 100 100)" />
                  <circle cx="100" cy="100" r="80" fill="transparent" stroke="#ef4444" strokeWidth="160"
                    strokeDasharray={`${anomalyPercentage * 5.03} 503`} 
                    strokeDashoffset={`-${normalPercentage * 5.03}`}
                    transform="rotate(-90 100 100)" />
                </svg>
              </div>
              <div className="pie-legend">
                <div className="legend-item">
                  <span className="legend-color" style={{background: '#10b981'}}></span>
                  <span>Normal: {normalCount} ({normalPercentage.toFixed(1)}%)</span>
                </div>
                <div className="legend-item">
                  <span className="legend-color" style={{background: '#ef4444'}}></span>
                  <span>Anomalies: {stats.anomalies} ({anomalyPercentage.toFixed(1)}%)</span>
                </div>
              </div>
            </div>
          ) : (
            <p style={{ textAlign: 'center', padding: '2rem' }}>No data available</p>
          )}
        </div>

        {/* Category Breakdown */}
        <div className="card chart-card">
          <h2>💼 Category Breakdown</h2>
          {Object.keys(stats.categories).length > 0 ? (
            <div className="custom-bar-chart">
              {Object.entries(stats.categories).map(([category, amount]) => {
                const percentage = (amount / stats.totalAmount) * 100;
                return (
                  <div key={category} className="bar-item">
                    <div className="bar-label">{category}</div>
                    <div className="bar-container">
                      <div className="bar-fill" style={{width: `${percentage}%`}}>
                        <span className="bar-value">{formatCurrency(amount)}</span>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <p style={{ textAlign: 'center', padding: '2rem' }}>No data available</p>
          )}
        </div>
      </div>

      {/* Timeline Chart */}
      <div className="card">
        <h2>📅 Transaction Timeline (Last 10 Days)</h2>
        {stats.timelineData.length > 0 ? (
          <div className="custom-line-chart">
            {stats.timelineData.map((day, index) => {
              const maxValue = Math.max(...stats.timelineData.map(d => d.normal + d.anomaly));
              const normalHeight = (day.normal / maxValue) * 100;
              const anomalyHeight = (day.anomaly / maxValue) * 100;
              return (
                <div key={index} className="timeline-bar-group">
                  <div className="timeline-bars">
                    <div className="timeline-bar normal" style={{height: `${normalHeight}%`}} title={`Normal: ${day.normal}`}></div>
                    <div className="timeline-bar anomaly" style={{height: `${anomalyHeight}%`}} title={`Anomaly: ${day.anomaly}`}></div>
                  </div>
                  <div className="timeline-label">{new Date(day.date).toLocaleDateString('en-IN', {month: 'short', day: 'numeric'})}</div>
                </div>
              );
            })}
          </div>
        ) : (
          <p style={{ textAlign: 'center', padding: '2rem' }}>No timeline data available</p>
        )}
        <div className="chart-legend">
          <div className="legend-item">
            <span className="legend-color" style={{background: '#10b981'}}></span>
            <span>Normal Transactions</span>
          </div>
          <div className="legend-item">
            <span className="legend-color" style={{background: '#ef4444'}}></span>
            <span>Anomalies</span>
          </div>
        </div>
      </div>

      {/* ML Model Info */}
      <div className="card">
        <h2>🔬 Model Information</h2>
        <div className="model-info-grid">
          <div className="info-item">
            <strong>Algorithm:</strong>
            <span>Isolation Forest</span>
          </div>
          <div className="info-item">
            <strong>Features Used:</strong>
            <span>6 (Amount, Category, Description Length, Log Scale, Amount in Lakhs, High Amount Flag)</span>
          </div>
          <div className="info-item">
            <strong>Training Data:</strong>
            <span>{stats.totalEntries} transactions</span>
          </div>
          <div className="info-item">
            <strong>Contamination Rate:</strong>
            <span>10% (Expected anomaly percentage)</span>
          </div>
          <div className="info-item">
            <strong>Model Status:</strong>
            <span className={stats.totalEntries >= 10 ? 'status-active' : 'status-inactive'}>
              {stats.totalEntries >= 10 ? '✅ Active (ML-based)' : '⚠️ Rule-based (Need 10+ entries)'}
            </span>
          </div>
          <div className="info-item">
            <strong>Detection Method:</strong>
            <span>{stats.totalEntries >= 10 ? 'Machine Learning' : 'Rule-based Fallback'}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;
